#include <semaphore.h>
#include <errno.h>

sem_t slots;                          /* ceiling of the bounded resource */
sem_init(&slots, 0, 8);               /* 0 = thread-shared, 8 permits     */

while (sem_wait(&slots) == -1 && errno == EINTR) { /* restart */ }
use_resource();
sem_post(&slots);                     /* on every exit path */
sem_destroy(&slots);

